//vcs coverage off
//`include "fsm_full.v"

module fsm_full_tb();

// === Global Sync Signal ===
reg llm_go_signal = 1;

reg clock , reset ;
reg instrument_clock;
reg req_0 , req_1 ,  req_2 , req_3; 
wire gnt_0 , gnt_1 , gnt_2 , gnt_3 ;

integer f;

initial begin
  f = $fopen("output.txt");
  $display("time\t    req_0 req_1 req_2 req_3 gnt_0 gnt_1 gnt_2 gnt_3");
  $fwrite(f, "time,gnt_0,gnt_1,gnt_2,gnt_3\n");
  $monitor("%0d\t    %b  %b  %b  %b  %b  %b  %b  %b", 
    $time, req_0, req_1, req_2, req_3, gnt_0, gnt_1, gnt_2, gnt_3);
  forever begin
    //@(posedge clock);
    #1
    $fwrite(f, "%0d,%b,%b,%b,%b\n", 
     $time, gnt_0, gnt_1, gnt_2, gnt_3);
  end
end

initial begin

  #4
  clock = 0;
  instrument_clock = 0;
      wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

  reset = 0;
  req_0 = 0;
  req_1 = 0;
  req_2 = 0;
  req_3 = 0;
  #10 reset = 1;
  #10 reset = 0;
  #10 req_0 = 1;
  #20 req_0 = 0;
  #10 req_1 = 1;
  #20 req_1 = 0;
  #10 req_2 = 1;
  #20 req_2 = 0;
  #10 req_3 = 1;
  #20 req_3 = 0;
  #10
  $fclose(f);
  $finish;
end

always
 #2 clock = ~clock;

always
  #8 instrument_clock = ~instrument_clock;

fsm_full U_fsm_full(
clock , // Clock
reset , // Active high reset
req_0 , // Active high request from agent 0
req_1 , // Active high request from agent 1
req_2 , // Active high request from agent 2
req_3 , // Active high request from agent 3
gnt_0 , // Active high grant to agent 0
gnt_1 , // Active high grant to agent 1
gnt_2 , // Active high grant to agent 2
gnt_3   // Active high grant to agent 3
);

initial begin
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

#20000
$finish;
end



// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. THEN WAIT for original tests
    // The synchronization signal ensures we run before the original testbench
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    $display("LLM: Starting Mutation Tests...");

    // Initialize signals to deterministic values
    // Explicitly set clock to 0 to ensure the oscillator in the TB starts correctly if it was waiting
    clock = 0;
    reset = 0;
    req_0 = 0;
    req_1 = 0;
    req_2 = 0;
    req_3 = 0;

    // Wait for clock stability and alignment
    #10;

    // --- RESET TEST ---
    // Assert reset to ensure FSM starts at IDLE and clears any unknown states
    reset = 1;
    @(posedge clock);
    reset = 0;
    @(posedge clock);

    // --- PRIORITY TEST (IDLE STATE) ---
    // Assert all requests simultaneously to verify priority logic:
    // Expected Priority: req_0 > req_1 > req_2 > req_3
    $display("LLM: Testing Priority Logic (req_0 > req_1 > req_2 > req_3)");
    req_0 = 1; req_1 = 1; req_2 = 1; req_3 = 1;
    @(posedge clock); 
    // Expect transition to GNT0

    // Drop req_0, expect transition GNT0 -> IDLE -> GNT1
    // Note: FSM logic dictates return to IDLE before granting next agent
    req_0 = 0;
    @(posedge clock); // Transition to IDLE
    @(posedge clock); // Transition to GNT1 (since req_1 is high)

    // Drop req_1, expect transition GNT1 -> IDLE -> GNT2
    req_1 = 0;
    @(posedge clock); // Transition to IDLE
    @(posedge clock); // Transition to GNT2 (since req_2 is high)

    // Drop req_2, expect transition GNT2 -> IDLE -> GNT3
    req_2 = 0;
    @(posedge clock); // Transition to IDLE
    @(posedge clock); // Transition to GNT3 (since req_3 is high)

    // Drop req_3, expect transition GNT3 -> IDLE
    req_3 = 0;
    @(posedge clock); // Transition to IDLE
    @(posedge clock); // Stay IDLE (All reqs 0)

    // --- HOLD STATE TEST ---
    // Verify that FSM stays in GNT state as long as the specific req is high
    // This targets mutations in the "else begin next_state = GNTx" branches
    $display("LLM: Testing State Hold Logic");

    // Test GNT0 Hold
    req_0 = 1;
    @(posedge clock); // Transition to GNT0
    @(posedge clock); // Should stay GNT0
    @(posedge clock); // Should stay GNT0
    req_0 = 0;
    @(posedge clock); // Transition to IDLE

    // Test GNT1 Hold
    req_1 = 1;
    @(posedge clock); // Transition to GNT1
    @(posedge clock); // Should stay GNT1
    req_1 = 0;
    @(posedge clock); // Transition to IDLE

    // Test GNT2 Hold
    req_2 = 1;
    @(posedge clock); // Transition to GNT2
    @(posedge clock); // Should stay GNT2
    req_2 = 0;
    @(posedge clock); // Transition to IDLE

    // Test GNT3 Hold
    req_3 = 1;
    @(posedge clock); // Transition to GNT3
    @(posedge clock); // Should stay GNT3
    req_3 = 0;
    @(posedge clock); // Transition to IDLE

    // --- RESET DURING OPERATION ---
    // Verify reset works correctly from a non-IDLE state
    // Targets control flow mutations where reset might be ignored in certain states
    $display("LLM: Testing Reset during operation");
    req_2 = 1;
    @(posedge clock); // Transition to GNT2
    reset = 1;        // Assert Reset asynchronously (or synchronously depending on design, here sync logic)
    @(posedge clock); // Should force transition to IDLE and clear grants
    reset = 0;
    req_2 = 0;
    @(posedge clock);

    // --- INTERLEAVED REQUESTS ---
    // Test transitions between different requests to ensure no state aliasing
    $display("LLM: Testing Interleaved Requests");
    req_0 = 1; req_3 = 1;
    @(posedge clock); // Transition to GNT0
    req_0 = 0;
    @(posedge clock); // Transition to IDLE
    @(posedge clock); // Transition to GNT3
    req_3 = 0;
    @(posedge clock); // Transition to IDLE

    // --- TIMING / GLITCH TEST ---
    // Change inputs shortly after clock edge to test setup/hold robustness
    // and ensure non-blocking assignments are handling updates correctly
    req_1 = 1;
    @(posedge clock); // Transition to GNT1
    #1 req_1 = 0;     // Drop request immediately after clock
    @(posedge clock); // Should transition to IDLE on next edge

    // 4. Cleanup and Handover
    #20;
    $display("LLM: Tests Finished. Handing over to Original TB...");
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (f != 0) $fclose(f);
    $finish;
end

endmodule

